def next_smallest_palindrome(n):
    # Convert the number to a string to work with its digits
    n_str = str(n)
    # Determine the length of the number
    len_n = len(n_str)

    # Find the middle index
    mid = len_n // 2

    # Split the number into left and right halves
    left = n_str[:mid]
    right = n_str[-mid:]

    # If the number is a palindrome, increment the middle digit(s)
    if n_str == n_str[::-1]:
        if len_n % 2 == 0:
            mid_digit = int(n_str[mid-1:mid+1])
            next_mid_digit = str(mid_digit + 1).zfill(2)
            return int(left[:-1] + next_mid_digit + right[1:])
        else:
            mid_digit = int(n_str[mid])
            next_mid_digit = mid_digit + 1
            return int(left[:-1] + str(next_mid_digit) + right[1:])

    # If not a palindrome, increment the left half and mirror it to the right
    left_int = int(left)
    next_left = str(left_int + 1)
    if len_n % 2 == 0:
        next_right = next_left[::-1]
    else:
        next_right = next_left[:-1] + next_left[-1] + next_left[-2::-1]

    return int(next_left + next_right)
```

