        start = 0
        while start < i:
            sublist[start], sublist[i] = sublist[i], sublist[start]
            start += 1
            i -= 1

    n = len(arr)
    curr_size = n
    while curr_size > 1:
        max_idx = 0
        for i in range(1, curr_size):
            if arr[i] > arr[max_idx]:
                max_idx = i
        flip(arr, max_idx)
        arr[0], arr[curr_size - 1] = arr[curr_size - 1], arr[0]
        curr_size -= 1
    return arr
