    result = []
    seen = {}
    for tup in tuples_list:
        if tup[0] in seen:
            seen[tup[0]].append(tup[1])
        else:
            seen[tup[0]] = [tup[1]]
    for key, value in seen.items():
        result.append((key,) + tuple(value))
        # Add additional tuple for the repeated keys
        if tuples_list.count((key, value[0])) > 1:
